# patch261 : « Ta boutique », la boutique qui tourne (avec s2-60)
import pathlib
def rep(s, a, b, n=1):
    assert s.count(a) == n, (a[:90], s.count(a)); return s.replace(a, b)
JS = "\n// ---------- patch261 : « Ta boutique », la boutique qui tourne (s2-60) ----------\n// Idée d'Oshannir : des communes qui te manquent, 4 par jour (communes, peu communes)\n// et 3 par semaine (rare, épique, légendaire), avec une remise. Une carte s'achète une fois.\nlet boutiqueTournante = null;      // ma_boutique()\nlet boutiqueTournanteLu = 0;\nlet bqrMinuteur = null;\nconst BQR_HORLOGE = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg>';\nasync function chargerBoutiqueTournante(){\n  const { data, error } = await sb.rpc('ma_boutique');\n  boutiqueTournante = !error && data && data.ouverte ? data : null;\n  boutiqueTournanteLu = Date.now();\n  renderBoutiqueTournante();\n}\nfunction bqrReste(sec){\n  const s = Math.max(0, sec - (Date.now() - boutiqueTournanteLu) / 1000);\n  if(s < 60) return 'Nouvelle sélection…';\n  const j = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);\n  return 'Change dans ' + (j >= 1 ? j + ' j' + (h ? ' ' + h + ' h' : '') : h >= 1 ? h + ' h ' + String(m).padStart(2, '0') : m + ' min');\n}\nfunction renderBoutiqueTournante(){\n  const el = document.getElementById('bqTourne');\n  if(!el) return;\n  const B = boutiqueTournante;\n  el.hidden = !B;\n  if(!B){ el.innerHTML = ''; return; }\n  const solde = boutiqueCache ? Number(boutiqueCache.solde) : Number(B.solde) || 0;\n  const item = (x) => {\n    const tier = TIERS.find(t => t.id === x.tier) || TIERS[0];\n    const carte = makeCardEl({ code: x.code, nom: x.nom, dept: x.dept, pop: Number(x.pop) || 0, tier, rank: Number(x.rang) || 0, tierSize: Number(x.palier_total) || 0 }, () => {});\n    carte.classList.add('flipped');\n    let action;\n    if(x.achete) action = '<span class=\"bqr-fait\">✓ Dans ta collection</span>';\n    else if(x.possede) action = '<span class=\"bqr-deja\">Déjà dans ta collection</span>';\n    else action = `<button class=\"bq-btn\" data-bqr-periode=\"${x.periode}\" data-bqr-case=\"${x.case}\" data-prix=\"${x.prix}\" data-libelle=\"Acheter\"${solde < x.prix ? ' data-court=\"1\"' : ''}>Acheter</button>`;\n    const libre = !x.achete && !x.possede;\n    return `<div class=\"bqr-item ${tier.id}${x.achete ? ' achete' : ''}${x.possede ? ' deja' : ''}\">\n        <div class=\"bqr-carte\">${carte.outerHTML}${libre ? `<span class=\"bqr-remise\">−${x.remise} %</span>` : ''}${libre && x.album ? `<span class=\"bqr-album\">Album · ${echapperTexte(x.album)}</span>` : ''}</div>\n        <div class=\"bqr-prix\"><s>${Number(x.base).toLocaleString('fr-FR')}</s><b>${Number(x.prix).toLocaleString('fr-FR')}<small>TP</small></b></div>\n        ${action}</div>`;\n  };\n  const jour = (B.cartes || []).filter(x => x.periode === 'jour');\n  const semaine = (B.cartes || []).filter(x => x.periode === 'semaine');\n  el.innerHTML = `<div class=\"bqr\">\n      <div class=\"bqr-tete\"><h2>Ta boutique</h2><p>Que des communes qui te manquent, rien que pour toi. Chaque carte s’achète une fois.</p></div>\n      <div class=\"bqr-rang\">Du jour<span class=\"bqr-minuteur\" data-fin=\"${B.fin_jour}\">${BQR_HORLOGE}${bqrReste(B.fin_jour)}</span></div>\n      ${jour.length ? `<div class=\"bqr-grille\">${jour.map(item).join('')}</div>` : '<p class=\"bqr-vide\">Tu as déjà toutes ces communes : bravo !</p>'}\n      <div class=\"bqr-rang\">De la semaine<span class=\"bqr-minuteur\" data-fin=\"${B.fin_semaine}\">${BQR_HORLOGE}${bqrReste(B.fin_semaine)}</span></div>\n      ${semaine.length ? `<div class=\"bqr-grille semaine\">${semaine.map(item).join('')}</div>` : '<p class=\"bqr-vide\">Tu as déjà toutes ces communes : bravo !</p>'}\n      <p class=\"bqr-note\">Les cartes achetées en TP ne s’échangent pas et ne vont pas à la Bourse. Elles ne comptent pas dans les 3 paquets de boutique par jour.</p>\n    </div>`;\n  clearInterval(bqrMinuteur);\n  bqrMinuteur = setInterval(() => {\n    const zone = document.getElementById('bqTourne');\n    if(!zone || !zone.isConnected || !boutiqueTournante){ clearInterval(bqrMinuteur); return; }\n    let fini = false;\n    zone.querySelectorAll('.bqr-minuteur').forEach(m => {\n      const f = Number(m.dataset.fin);\n      if(f - (Date.now() - boutiqueTournanteLu) / 1000 <= 0) fini = true;\n      m.innerHTML = BQR_HORLOGE + bqrReste(f);\n    });\n    if(fini){ clearInterval(bqrMinuteur); chargerBoutiqueTournante(); }\n  }, 30000);\n}\nasync function acheterCarteBoutique(periode, n){\n  const { data, error } = await sb.rpc('ma_boutique_acheter', { p_periode: periode, p_case: Number(n) });\n  if(error){ notifier({ type: 'erreur', titre: 'Achat impossible', texte: messageLisible(error.message) }); return chargerBoutiqueTournante(); }\n  boutiqueTournante = data && data.ouverte ? data : null;\n  boutiqueTournanteLu = Date.now();\n  if(boutiqueCache && data && data.solde != null){ boutiqueCache.solde = data.solde; renderBoutique(); }\n  renderBoutiqueTournante();\n  const a = data && data.achat;\n  notifier({ type: 'succes', titre: a ? a.nom + ' rejoint ta collection' : 'Carte achetée', texte: a ? `${(TIERS.find(t => t.id === a.tier) || {}).label || ''} · ${DEPT_NAMES[a.dept] || a.dept} (${a.dept})` : '' });\n  if(typeof chargerCollectionTerra === 'function') chargerCollectionTerra();\n  if(typeof loadPackStatus === 'function') loadPackStatus();   // le solde affiché en haut\n}\n"
CSS = "/* ---------- patch261 : « Ta boutique », la boutique qui tourne ---------- */\n.bqr{ margin:4px 0 18px; padding:14px 14px 16px; border-radius:16px; border:1px solid rgba(240,180,41,.35);\n  background:radial-gradient(120% 90% at 50% 0%, rgba(240,180,41,.13), rgba(240,180,41,0) 60%), var(--nuit-2, #162C4B); }\n.bqr-tete{ display:flex; align-items:flex-end; gap:10px; flex-wrap:wrap; }\n.bqr-tete h2{ margin:0; font-family:var(--titre); font-weight:900; font-size:1.55rem; line-height:1; }\n.bqr-tete p{ margin:4px 0 0; font-size:.78rem; color:var(--brume); width:100%; }\n.bqr-rang{ display:flex; align-items:center; gap:8px; margin:14px 2px 8px; font-size:.7rem; letter-spacing:.09em; text-transform:uppercase; color:#C8D5E6; font-weight:600; }\n.bqr-rang .bqr-minuteur{ margin-left:auto; display:inline-flex; align-items:center; gap:5px; padding:3px 9px; border-radius:999px; background:rgba(15,31,56,.75);\n  border:1px solid rgba(169,188,212,.2); font-size:.7rem; letter-spacing:0; text-transform:none; color:#E6EDF7; font-weight:600; white-space:nowrap; }\n.bqr-rang .bqr-minuteur svg{ width:13px; height:13px; opacity:.8; }\n.bqr-grille{ display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; }\n.bqr-grille.semaine{ grid-template-columns:repeat(3, minmax(0,1fr)); }\n.bqr-item{ position:relative; display:flex; flex-direction:column; align-items:center; gap:6px; padding:8px 6px 10px; border-radius:12px;\n  background:rgba(11,24,48,.55); border:1px solid rgba(169,188,212,.12); }\n.bqr-carte{ position:relative; width:118px; height:165px; }\n.bqr-carte .card{ transform:scale(.627); transform-origin:0 0; cursor:default; }\n.bqr-carte .card .card-inner{ transform:rotateY(180deg); }\n.bqr-remise{ position:absolute; top:-6px; right:-8px; z-index:3; padding:3px 7px; border-radius:7px; font:900 .95rem/1 var(--titre); letter-spacing:.02em;\n  color:#fff; background:linear-gradient(180deg,#F05A5F,#C7343A); box-shadow:0 3px 8px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.25); transform:rotate(6deg); }\n.bqr-album{ position:absolute; left:50%; bottom:-7px; z-index:3; transform:translateX(-50%); white-space:nowrap; padding:3px 8px; border-radius:999px; font-size:.64rem; font-weight:600;\n  color:#06210f; background:linear-gradient(180deg,#7cf5b0,#2fbf6e); box-shadow:0 2px 6px rgba(0,0,0,.4); }\n.bqr-prix{ display:flex; align-items:baseline; gap:6px; margin-top:4px; }\n.bqr-prix s{ font-size:.74rem; color:#7B8FAB; }\n.bqr-prix b{ font-family:var(--titre); font-weight:900; font-size:1.2rem; color:#FFE08A; }\n.bqr-prix b small{ font-family:'Instrument Sans', system-ui, sans-serif; font-size:.68rem; font-weight:600; color:#C9AE97; margin-left:2px; }\n.bqr-item .bq-btn{ width:100%; margin:0; padding:7px 6px; font-size:.8rem; }\n.bqr-item.achete .bqr-carte{ opacity:.45; filter:saturate(.4); }\n.bqr-fait{ display:flex; align-items:center; justify-content:center; gap:5px; width:100%; padding:7px 6px; border-radius:9px; font-size:.78rem; font-weight:600;\n  color:#5BE3A6; background:rgba(43,212,139,.12); border:1px solid rgba(43,212,139,.3); }\n.bqr-grille.semaine .bqr-item{ background:linear-gradient(180deg, rgba(240,180,41,.08), rgba(11,24,48,.55)); border-color:rgba(240,180,41,.25); }\n.bqr-item.legendaire{ border-color:rgba(240,180,41,.65); box-shadow:0 0 18px rgba(240,180,41,.18); }\n.bqr-note{ margin:12px 2px 0; font-size:.72rem; color:#7B8FAB; line-height:1.45; }\n@media (max-width:560px){\n  .bqr-grille{ grid-template-columns:repeat(2, minmax(0,1fr)); }\n  .bqr-grille.semaine{ grid-template-columns:repeat(3, minmax(0,1fr)); gap:6px; }\n  .bqr-grille.semaine .bqr-carte{ width:96px; height:134px; }\n  .bqr-grille.semaine .bqr-carte .card{ transform:scale(.51); }\n  .bqr-grille.semaine .bqr-prix b{ font-size:1.05rem; }\n  .bqr-grille.semaine .bq-btn{ font-size:.72rem; padding:6px 4px; }\n}\n.bqr-item.deja .bqr-carte{ opacity:.45; filter:saturate(.4); }\n.bqr-deja{ display:flex; align-items:center; justify-content:center; width:100%; padding:7px 6px; border-radius:9px; font-size:.74rem; font-weight:600; color:#A9BCD4; background:rgba(169,188,212,.08); border:1px solid rgba(169,188,212,.2); text-align:center; }\n.bqr-vide{ margin:0; font-size:.8rem; color:var(--brume); }\n"
f = pathlib.Path('app.js'); s = f.read_text(encoding='utf-8')
# la boutique charge aussi « Ta boutique »
s = rep(s, """  bqeVerifierAcces();
  renderBoutique();""", """  bqeVerifierAcces();
  renderBoutique();
  if(!silencieux || boutiqueTournante) chargerBoutiqueTournante();   // patch261""")
# confirmation : un bouton peut garder son libellé (« Acheter ») au lieu du prix
s = rep(s, "  document.querySelectorAll('.bq-btn.confirmer').forEach(x => { x.classList.remove('confirmer'); x.textContent = bqPrix(x.dataset.prix); });",
           "  document.querySelectorAll('.bq-btn.confirmer').forEach(x => { x.classList.remove('confirmer'); x.textContent = x.dataset.libelle || bqPrix(x.dataset.prix); });")
s = rep(s, "      btn.textContent = bqPrix(btn.dataset.prix);\n",
           "      btn.textContent = btn.dataset.libelle || bqPrix(btn.dataset.prix);\n")
# l'achat
s = rep(s, "  else if(btn.dataset.bqDos) acheterDosBoutique(btn.dataset.bqDos).finally(() => { btn.disabled = false; });",
"""  else if(btn.dataset.bqDos) acheterDosBoutique(btn.dataset.bqDos).finally(() => { btn.disabled = false; });
  else if(btn.dataset.bqrPeriode) acheterCarteBoutique(btn.dataset.bqrPeriode, btn.dataset.bqrCase).finally(() => { if(btn.isConnected) btn.disabled = false; });   // patch261""")
s = rep(s, "async function acheterDosBoutique(id){", JS + "\nasync function acheterDosBoutique(id){")
f.write_text(s, encoding='utf-8')

f = pathlib.Path('style.css'); s = f.read_text(encoding='utf-8')
assert 'patch261' not in s
f.write_text(s.rstrip('\n') + '\n' + CSS, encoding='utf-8')

f = pathlib.Path('index.html'); s = f.read_text(encoding='utf-8')
s = rep(s, """      <div class="puces" id="bqStatut"><span class="puce">Chargement…</span></div>""",
"""      <div class="puces" id="bqStatut"><span class="puce">Chargement…</span></div>
      <div class="bq-terra-seul" id="bqTourne" hidden></div>""")
s = rep(s, "<p><b>Boutique</b> (en TerraPoints) : ",
           "<p><b>Ta boutique</b> : chaque jour, 4 communes qui te manquent (communes et peu communes) ; chaque semaine, une rare, une épique et une légendaire. Chacune a une remise de 20 à 70 % et s'achète une fois. Payées en TP, elles ne s'échangent pas.</p>\n            <p><b>Boutique</b> (en TerraPoints) : ")
f.write_text(s, encoding='utf-8')
